{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Delpazolid (LCB01-0371), an N-aryl oxazolidinone closely matching the query's oxazolidinone/fluorophenyl core, had 99.75% absolute oral bioavailability in healthy subjects after 800 mg PO vs IV.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Linezolid, the prototypical oxazolidinone, has essentially 100% absolute oral bioavailability in humans, supporting high absorption for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Milvexian, a large lipophilic clinical drug with high transferability, showed 58.2% absolute bioavailability under fasted conditions in healthy participants.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Ketanserin showed 60% absolute bioavailability after a 40 mg oral tablet in fasted subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Zalcitabine had 80% absolute oral bioavailability (range 54–127%) under fasting conditions in patients with advanced HIV infection.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Vorapaxar has approximately 100% oral bioavailability in humans without regard to food.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Pradigastat had about 40% absolute oral bioavailability in humans, still well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability between roughly 40% and 100% in humans, including fasted conditions; the query's oxazolidinone core is directly associated with near-complete absorption. Thus F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule; prediction relies on close analogues.",
    "Fasted-state data are not available for the closest oxazolidinone analogues (delpazolid, linezolid), though their F is ~100% and food-independent.",
    "Formulation effects are not specified for the query; some analogues show formulation-dependent F, but all remain above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

